CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261013155213_InitialMenu') THEN
    CREATE TABLE "MenuItems" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" text NOT NULL,
        "Category" text NOT NULL,
        "Price" numeric(10,2) NOT NULL,
        "Description" text NOT NULL,
        "Emoji" text NOT NULL,
        "Tag" text NOT NULL,
        CONSTRAINT "PK_MenuItems" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261013155213_InitialMenu') THEN
    INSERT INTO "MenuItems" ("Id", "Category", "Description", "Emoji", "Name", "Price", "Tag")
    VALUES (1, 'Meals', 'Grilled chicken, fragrant rice and a bright garden salad.', '🍛', 'Chicken rice bowl', 650.0, 'Campus favourite');
    INSERT INTO "MenuItems" ("Id", "Category", "Description", "Emoji", "Name", "Price", "Tag")
    VALUES (2, 'Meals', 'Roasted vegetables, chickpeas and fresh greens.', '🥗', 'Veggie power bowl', 520.0, 'Vegetarian');
    INSERT INTO "MenuItems" ("Id", "Category", "Description", "Emoji", "Name", "Price", "Tag")
    VALUES (3, 'Snacks', 'A toasted bun, crispy chicken and our house sauce.', '🍔', 'Classic chicken burger', 480.0, 'Quick bite');
    INSERT INTO "MenuItems" ("Id", "Category", "Description", "Emoji", "Name", "Price", "Tag")
    VALUES (4, 'Snacks', 'Golden toast with melted cheese and ripe tomatoes.', '🥪', 'Cheese and tomato toast', 320.0, 'Vegetarian');
    INSERT INTO "MenuItems" ("Id", "Category", "Description", "Emoji", "Name", "Price", "Tag")
    VALUES (5, 'Drinks', 'Fresh lime, a little sweetness and plenty of ice.', '🍋', 'Iced lime cooler', 220.0, 'Refreshing');
    INSERT INTO "MenuItems" ("Id", "Category", "Description", "Emoji", "Name", "Price", "Tag")
    VALUES (6, 'Drinks', 'Smooth, slow-brewed coffee for your next lecture.', '☕', 'Cold brew coffee', 350.0, 'Study fuel');
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261013155213_InitialMenu') THEN
    PERFORM setval(
        pg_get_serial_sequence('"MenuItems"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "MenuItems") + 1,
            nextval(pg_get_serial_sequence('"MenuItems"', 'Id'))),
        false);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261013155213_InitialMenu') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261013155213_InitialMenu', '8.0.11');
    END IF;
END $EF$;
COMMIT;

ALTER TABLE public."MenuItems" ENABLE ROW LEVEL SECURITY;`nALTER TABLE public."__EFMigrationsHistory" ENABLE ROW LEVEL SECURITY;`nREVOKE ALL ON TABLE public."MenuItems", public."__EFMigrationsHistory" FROM anon, authenticated;
